import React, { useState, useEffect, useRef, useCallback } from 'react';

// ── Moved OUTSIDE to prevent re-mount on every render ──
const InteractiveViewer = ({
  selectedLocation,
  locationMap,
  isFullscreen,
  setIsFullscreen,
  zoomLevel,
  handleZoomIn,
  handleZoomOut,
  resetView,
  showHotspots,
  setShowHotspots,
  showInfo,
  toggleInfo,
  audioEnabled,
  toggleAudio,
  viewMode,
  changeViewMode,
  isPlaying,
  chatOpen,
  setChatOpen,
  chatMessages,
  chatInput,
  setChatInput,
  handleChatSend,
}) => {
  const [rotation, setRotation] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [startPosition, setStartPosition] = useState({ x: 0, y: 0 });
  const [currentHotspot, setCurrentHotspot] = useState(null);
  const viewerRef = useRef(null);

  const handleMouseDown = useCallback((e) => {
    setIsDragging(true);
    setStartPosition({ x: e.clientX, y: e.clientY });
  }, []);

  const handleTouchStart = useCallback((e) => {
    setIsDragging(true);
    setStartPosition({ x: e.touches[0].clientX, y: e.touches[0].clientY });
  }, []);

  const handleMouseMove = useCallback((e) => {
    if (!isDragging) return;
    const deltaX = e.clientX - startPosition.x;
    const deltaY = e.clientY - startPosition.y;
    setRotation((prev) => ({
      x: Math.max(-90, Math.min(90, prev.x + deltaY * 0.4)),
      y: prev.y + deltaX * 0.4,
    }));
    setStartPosition({ x: e.clientX, y: e.clientY });
  }, [isDragging, startPosition]);

  const handleTouchMove = useCallback((e) => {
    if (!isDragging) return;
    const deltaX = e.touches[0].clientX - startPosition.x;
    const deltaY = e.touches[0].clientY - startPosition.y;
    setRotation((prev) => ({
      x: Math.max(-90, Math.min(90, prev.x + deltaY * 0.4)),
      y: prev.y + deltaX * 0.4,
    }));
    setStartPosition({ x: e.touches[0].clientX, y: e.touches[0].clientY });
  }, [isDragging, startPosition]);

  const handleMouseUp = useCallback(() => setIsDragging(false), []);
  const handleTouchEnd = useCallback(() => setIsDragging(false), []);

  const handleWheel = useCallback((e) => {
    e.preventDefault();
    if (e.deltaY < 0) handleZoomIn();
    else handleZoomOut();
  }, [handleZoomIn, handleZoomOut]);

  const handleHotspotClick = useCallback((hotspot, e) => {
    e.stopPropagation();
    setCurrentHotspot(hotspot);
    setTimeout(() => setCurrentHotspot(null), 4000);
  }, []);

  useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      window.addEventListener('touchmove', handleTouchMove, { passive: true });
      window.addEventListener('touchend', handleTouchEnd);
      return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        window.removeEventListener('mouseup', handleMouseUp);
        window.removeEventListener('touchmove', handleTouchMove);
        window.removeEventListener('touchend', handleTouchEnd);
      };
    }
  }, [isDragging, handleMouseMove, handleMouseUp, handleTouchMove, handleTouchEnd]);

  useEffect(() => {
    const el = viewerRef.current;
    if (!el) return;
    el.addEventListener('wheel', handleWheel, { passive: false });
    return () => el.removeEventListener('wheel', handleWheel);
  }, [handleWheel]);

  useEffect(() => {
    const handleKeyDown = (e) => {
      if (!isPlaying) return;
      const step = 8;
      switch (e.key) {
        case 'ArrowUp':    setRotation((p) => ({ ...p, x: Math.max(-90, p.x - step) })); break;
        case 'ArrowDown':  setRotation((p) => ({ ...p, x: Math.min(90, p.x + step) })); break;
        case 'ArrowLeft':  setRotation((p) => ({ ...p, y: p.y - step })); break;
        case 'ArrowRight': setRotation((p) => ({ ...p, y: p.y + step })); break;
        case '+': handleZoomIn(); break;
        case '-': handleZoomOut(); break;
        case '0': resetView(); break;
        case 'Escape':
          if (isFullscreen) setIsFullscreen(false);
          if (currentHotspot) setCurrentHotspot(null);
          break;
        default: break;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPlaying, isFullscreen, currentHotspot, handleZoomIn, handleZoomOut, resetView, setIsFullscreen]);

  const loc = locationMap[selectedLocation];

  return (
    <div
      ref={viewerRef}
      className={`relative overflow-hidden select-none ${
        isFullscreen ? 'fixed inset-0 z-50' : 'h-[480px] rounded-2xl shadow-2xl'
      }`}
      style={{ cursor: isDragging ? 'grabbing' : 'grab', background: '#0f172a' }}
      onMouseDown={handleMouseDown}
      onTouchStart={handleTouchStart}
    >
      {/* ── Background image ── */}
      <div
        className="absolute inset-0 bg-center bg-cover"
        style={{
          backgroundImage: `url(${loc.image})`,
          transform: `rotateX(${rotation.x}deg) rotateY(${rotation.y}deg) scale(${zoomLevel})`,
          transition: isDragging ? 'none' : 'transform 0.12s ease-out',
          filter: viewMode === 'AR' ? 'sepia(0.4) saturate(1.8) hue-rotate(10deg)' : 'brightness(0.92)',
          willChange: 'transform',
        }}
      />

      {/* ── VR split line ── */}
      {viewMode === 'VR' && (
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          <div className="w-px h-full bg-white opacity-30" />
          <div className="absolute inset-0 rounded-full"
            style={{ boxShadow: 'inset 0 0 120px 60px rgba(0,0,0,0.6)' }} />
        </div>
      )}

      {/* ── Hotspots ── */}
      {showHotspots &&
        loc.hotspots.map((hotspot) => (
          <button
            key={hotspot.id}
            className="absolute flex items-center justify-center w-8 h-8 -translate-x-1/2 -translate-y-1/2 border-2 border-white rounded-full shadow-lg bg-rose-500/70"
            style={{
              left: `${hotspot.x}%`,
              top: `${hotspot.y}%`,
              animation: 'hotspotPulse 2s ease-in-out infinite',
            }}
            onClick={(e) => handleHotspotClick(hotspot, e)}
            title={hotspot.title}
          >
            <span className="text-xs font-bold text-white">+</span>
          </button>
        ))}

      {/* ── Hotspot popup ── */}
      {currentHotspot && (
        <div
          className="absolute z-20 w-64 max-w-xs p-4 text-white -translate-x-1/2 -translate-y-1/2 border shadow-2xl top-1/2 left-1/2 bg-black/80 backdrop-blur-md rounded-xl border-white/10"
          style={{ animation: 'fadeIn 0.25s ease-in-out' }}
        >
          <button
            className="absolute text-lg top-2 right-3 text-white/60 hover:text-white"
            onClick={() => setCurrentHotspot(null)}
          >✕</button>
          <h4 className="mb-1 text-base font-bold">{currentHotspot.title}</h4>
          <p className="text-sm text-white/80">{currentHotspot.description}</p>
        </div>
      )}

      {/* ── Top-right controls ── */}
      <div className="absolute flex gap-2 top-4 right-4">
        {[
          { icon: showInfo ? '🙈' : 'ⓘ', action: toggleInfo, title: 'Toggle info' },
          { icon: showHotspots ? '📍' : '🔍', action: () => setShowHotspots(!showHotspots), title: 'Toggle hotspots' },
          { icon: audioEnabled ? '🔊' : '🔇', action: toggleAudio, title: 'Toggle audio' },
          { icon: isFullscreen ? '⛶' : '⛶', action: () => setIsFullscreen(!isFullscreen), title: isFullscreen ? 'Exit fullscreen' : 'Fullscreen' },
        ].map((btn, i) => (
          <button
            key={i}
            onClick={btn.action}
            title={btn.title}
            className="flex items-center justify-center text-base text-white transition border rounded-full w-9 h-9 bg-black/50 backdrop-blur-sm hover:bg-black/70 border-white/10"
          >
            {btn.icon}
          </button>
        ))}
      </div>

      {/* ── Info panel ── */}
      {showInfo && (
        <div className="absolute max-w-xs p-4 text-white border shadow-xl top-4 left-4 bg-black/60 backdrop-blur-md rounded-xl border-white/10">
          <h4 className="mb-1 text-base font-bold">{selectedLocation}</h4>
          <p className="mb-3 text-xs leading-relaxed text-white/75">{loc.description}</p>
          <div className="flex gap-2">
            {['360', 'VR', 'AR'].map((mode) => (
              <button
                key={mode}
                className={`px-3 py-1 rounded-full text-xs font-medium transition ${
                  viewMode === mode
                    ? 'bg-blue-600 text-white shadow'
                    : 'bg-white/10 hover:bg-white/20 text-white/80'
                }`}
                onClick={() => changeViewMode(mode)}
              >
                {mode}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* ── D-pad navigation ── */}
      <div className="absolute p-2 border bottom-16 right-4 bg-black/40 backdrop-blur-sm rounded-xl border-white/10">
        <div className="flex justify-center mb-1">
          <button className="flex items-center justify-center w-8 h-8 text-sm text-white rounded-lg hover:bg-white/20"
            onClick={() => setRotation((p) => ({ ...p, x: Math.max(-90, p.x - 10) }))}>▲</button>
        </div>
        <div className="flex gap-1">
          <button className="flex items-center justify-center w-8 h-8 text-sm text-white rounded-lg hover:bg-white/20"
            onClick={() => setRotation((p) => ({ ...p, y: p.y - 10 }))}>◀</button>
          <button className="flex items-center justify-center w-8 h-8 text-sm text-white rounded-lg hover:bg-white/20"
            onClick={() => setRotation((p) => ({ ...p, x: Math.min(90, p.x + 10) }))}>▼</button>
          <button className="flex items-center justify-center w-8 h-8 text-sm text-white rounded-lg hover:bg-white/20"
            onClick={() => setRotation((p) => ({ ...p, y: p.y + 10 }))}>▶</button>
        </div>
      </div>

      {/* ── Zoom controls ── */}
      <div className="absolute flex flex-col gap-1 p-2 border bottom-16 left-4 bg-black/40 backdrop-blur-sm rounded-xl border-white/10">
        {[{ label: '+', action: handleZoomIn }, { label: '⟳', action: resetView }, { label: '−', action: handleZoomOut }].map((btn) => (
          <button
            key={btn.label}
            onClick={btn.action}
            className="flex items-center justify-center w-8 h-8 text-sm font-bold text-white rounded-lg hover:bg-white/20"
          >{btn.label}</button>
        ))}
      </div>

      {/* ── Bottom hint bar ── */}
      <div className="absolute flex items-center gap-3 px-4 py-2 text-xs text-white -translate-x-1/2 border rounded-full bottom-4 left-1/2 bg-black/50 backdrop-blur-sm border-white/10">
        <span>🖱 Drag to look</span>
        <span className="opacity-40">|</span>
        <span>🖱 Scroll to zoom</span>
        <span className="opacity-40">|</span>
        <span>📍 Tap hotspots</span>
      </div>

      {/* ── Chat ── */}
      <div className="absolute z-20 bottom-20 right-4">
        {chatOpen ? (
          <div className="flex flex-col overflow-hidden border shadow-2xl w-72 bg-gray-900/90 backdrop-blur-md border-white/10 rounded-2xl"
            style={{ height: '340px' }}>
            <div className="flex items-center justify-between px-4 py-3 border-b border-white/10 bg-blue-900/40">
              <div className="flex items-center gap-2">
                <span className="text-base">🤖</span>
                <span className="text-sm font-semibold text-white">Tour Guide AI</span>
                <span className="w-2 h-2 bg-green-400 rounded-full animate-pulse" />
              </div>
              <button className="text-white/60 hover:text-white" onClick={() => setChatOpen(false)}>✕</button>
            </div>
            <div className="flex-1 p-3 space-y-2 overflow-y-auto">
              {chatMessages.map((m, i) => (
                <div
                  key={i}
                  className={`text-xs px-3 py-2 rounded-xl max-w-[85%] leading-relaxed ${
                    m.isBot
                      ? 'bg-blue-800/50 text-white self-start'
                      : 'bg-white/10 text-white/90 ml-auto text-right'
                  }`}
                >
                  {m.text}
                </div>
              ))}
            </div>
            <form onSubmit={handleChatSend} className="flex gap-2 p-3 border-t border-white/10">
              <input
                className="flex-1 px-3 py-2 text-xs text-white border rounded-lg outline-none bg-white/10 placeholder-white/40 border-white/10 focus:border-blue-400"
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                placeholder="Ask about this place..."
              />
              <button type="submit" className="px-3 py-2 text-xs font-medium text-white transition bg-blue-600 rounded-lg hover:bg-blue-500">
                Send
              </button>
            </form>
          </div>
        ) : (
          <button
            onClick={() => setChatOpen(true)}
            className="flex items-center gap-2 px-4 py-3 text-sm text-white transition-all bg-blue-600 border rounded-full shadow-lg hover:bg-blue-500 hover:shadow-blue-500/30 hover:shadow-xl border-blue-400/30"
          >
            💬 <span className="font-medium">Ask Guide</span>
          </button>
        )}
      </div>
    </div>
  );
};

// ── Location card data ──
const LOCATION_COLORS = {
  'Betla National Park': { from: '#134e1a', to: '#1a7a2a', emoji: '🐯' },
  'Hundru Falls':        { from: '#1a3a5c', to: '#1e6fa8', emoji: '💧' },
  'Jonha Falls':         { from: '#1a3a5c', to: '#1e8fa8', emoji: '🌊' },
  'Baidyanath Dham':     { from: '#4a1a1a', to: '#8b2a2a', emoji: '🛕' },
  'Patratu Valley':      { from: '#2a3a1a', to: '#4a6a1a', emoji: '🏔️' },
};

const ARVR = () => {
  const [selectedLocation, setSelectedLocation] = useState('Betla National Park');
  const [previewUrl, setPreviewUrl]     = useState('');
  const [isLoading, setIsLoading]       = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showInfo, setShowInfo]         = useState(true);
  const [viewMode, setViewMode]         = useState('360');
  const [zoomLevel, setZoomLevel]       = useState(1);
  const [showHotspots, setShowHotspots] = useState(true);
  const [isPlaying, setIsPlaying]       = useState(false);
  const [audioEnabled, setAudioEnabled] = useState(false);
  const [showTutorial, setShowTutorial] = useState(true);
  const [chatOpen, setChatOpen]         = useState(false);
  const [chatInput, setChatInput]       = useState('');
  const [chatMessages, setChatMessages] = useState([
    { text: 'Welcome to the virtual tour! Ask me anything about this location.', isBot: true },
  ]);

  const locationMap = {
    'Betla National Park': {
      url: '[arvr.jharkhandtourism.com](https://arvr.jharkhandtourism.com/betla)',
      description: 'Explore the wilderness of Betla National Park, home to tigers, elephants, and diverse flora.',
      // Reliable Picsum IDs
      image: '[picsum.photos](https://picsum.photos/seed/betla/1600/900)',
      hotspots: [
        { id: 1, x: 30, y: 40, title: 'Jungle Trail',   description: 'Explore the dense forest pathways' },
        { id: 2, x: 60, y: 25, title: 'Historic Ruins', description: 'Discover ancient structures' },
        { id: 3, x: 70, y: 60, title: 'Watch Tower',    description: 'Panoramic views of the park' },
      ],
    },
    'Hundru Falls': {
      url: '[arvr.jharkhandtourism.com](https://arvr.jharkhandtourism.com/hundru)',
      description: 'Witness the majestic Hundru Falls, one of the highest waterfalls in Jharkhand.',
      image: '[picsum.photos](https://picsum.photos/seed/hundru/1600/900)',
      hotspots: [
        { id: 1, x: 50, y: 30, title: 'Top View',  description: 'See the waterfall from above' },
        { id: 2, x: 25, y: 60, title: 'Base Camp', description: 'Feel the mist on your face' },
        { id: 3, x: 75, y: 70, title: 'Viewpoint', description: 'Perfect photo opportunity' },
      ],
    },
    'Jonha Falls': {
      url: '[arvr.jharkhandtourism.com](https://arvr.jharkhandtourism.com/jonha)',
      description: 'Discover Jonha Falls, also known as Gautamdhara Falls. Serene surroundings await.',
      image: '[picsum.photos](https://picsum.photos/seed/jonha/1600/900)',
      hotspots: [
        { id: 1, x: 40, y: 50, title: 'Main Falls',       description: 'The primary waterfall view' },
        { id: 2, x: 60, y: 30, title: 'Rock Formations',  description: 'Unique geological features' },
        { id: 3, x: 20, y: 70, title: 'Bridge View',      description: 'Scenic overlook from the bridge' },
      ],
    },
    'Baidyanath Dham': {
      url: '[arvr.jharkhandtourism.com](https://arvr.jharkhandtourism.com/baidyanath)',
      description: 'Experience the spiritual aura of Baidyanath Dham, one of the twelve Jyotirlingas.',
      image: '[picsum.photos](https://picsum.photos/seed/baidyanath/1600/900)',
      hotspots: [
        { id: 1, x: 50, y: 40, title: 'Main Temple',    description: 'The sacred Jyotirlinga shrine' },
        { id: 2, x: 30, y: 60, title: 'Prayer Hall',    description: 'Space for devotional activities' },
        { id: 3, x: 70, y: 20, title: 'Temple Complex', description: 'Overview of the entire area' },
      ],
    },
    'Patratu Valley': {
      url: '[arvr.jharkhandtourism.com](https://arvr.jharkhandtourism.com/patratu)',
      description: 'Breathtaking views of Patratu Valley with its serpentine roads and lush landscapes.',
      image: '[picsum.photos](https://picsum.photos/seed/patratu/1600/900)',
      hotspots: [
        { id: 1, x: 40, y: 30, title: 'Valley Overview', description: 'Panoramic view of the valley' },
        { id: 2, x: 60, y: 50, title: 'Serpentine Road', description: 'The famous winding road' },
        { id: 3, x: 20, y: 70, title: 'Viewpoint',       description: 'Best spot for photography' },
      ],
    },
  };

  const handleShowPreview = () => {
    setPreviewUrl(locationMap[selectedLocation].url);
    setIsLoading(true);
    setIsPlaying(false);
    setTimeout(() => {
      setIsLoading(false);
      setIsPlaying(true);
    }, 2000);
  };

  const toggleInfo    = () => setShowInfo((p) => !p);
  const toggleAudio   = () => setAudioEnabled((p) => !p);
  const handleZoomIn  = useCallback(() => setZoomLevel((p) => Math.min(p + 0.2, 2.5)), []);
  const handleZoomOut = useCallback(() => setZoomLevel((p) => Math.max(p - 0.2, 0.5)), []);
  const resetView     = useCallback(() => setZoomLevel(1), []);

  const changeViewMode = (mode) => {
    setViewMode(mode);
    if (mode === 'VR') setTimeout(() => alert('VR mode would activate your headset in a real implementation'), 300);
  };

  const handleChatSend = (e) => {
    e.preventDefault();
    if (!chatInput.trim()) return;
    const userMsg = { text: chatInput, isBot: false };
    setChatMessages((prev) => [...prev, userMsg]);
    const q = chatInput.toLowerCase();
    setChatInput('');
    setTimeout(() => {
      let r = `Great choice! ${selectedLocation} is known for its unique geography and cultural significance.`;
      if (q.includes('best time'))   r = `Best time to visit ${selectedLocation} is October–March for pleasant weather.`;
      if (q.includes('how to reach'))r = `${selectedLocation} is well connected by road from Ranchi. Need transport details?`;
      if (q.includes('history'))     r = `Jharkhand has rich tribal heritage. ${selectedLocation} has been significant for centuries.`;
      if (q.includes('wildlife') || q.includes('animals')) r = `At ${selectedLocation} you might spot elephants, tigers, and deer species!`;
      if (q.includes('waterfall') || q.includes('height')) r = `The waterfalls here drop from over 300 feet — absolutely breathtaking!`;
      if (q.includes('hello') || q.includes('hi'))         r = `Hello! I'm your AI tour guide. Ask me anything about ${selectedLocation}.`;
      if (q.includes('weather'))     r = `The region currently has pleasant weather — perfect for exploration.`;
      setChatMessages((prev) => [...prev, { text: r, isBot: true }]);
    }, 900);
  };

  const colors = LOCATION_COLORS[selectedLocation];

  return (
    <div className={`min-h-screen bg-gradient-to-br from-slate-900 via-blue-950 to-slate-900 p-6 ${isFullscreen ? 'pt-0' : ''}`}>
      <style>{`
        @keyframes float        { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-10px)} }
        @keyframes fadeIn       { from{opacity:0;transform:translate(-50%,-50%) scale(0.95)} to{opacity:1;transform:translate(-50%,-50%) scale(1)} }
        @keyframes hotspotPulse { 0%,100%{box-shadow:0 0 0 0 rgba(239,68,68,0.6)} 50%{box-shadow:0 0 0 8px rgba(239,68,68,0)} }
      `}</style>

      {!isFullscreen && (
        <>
          {/* ── Header ── */}
          <div className="flex items-center justify-between mb-8">
            <div>
              <h2 className="text-3xl font-bold tracking-tight text-white">
                🌄 Jharkhand AR/VR Experience
              </h2>
              <p className="mt-1 text-sm text-slate-400">Virtual tours of Jharkhand's most stunning destinations</p>
            </div>
            <button
              onClick={() => setShowTutorial((p) => !p)}
              className="px-4 py-2 text-sm font-medium text-blue-300 transition border bg-blue-900/40 border-blue-700/40 rounded-xl hover:bg-blue-800/40"
            >
              {showTutorial ? '🙈 Hide Tips' : '💡 Show Tips'}
            </button>
          </div>

          {/* ── Tutorial banner ── */}
          {showTutorial && (
            <div className="flex items-start gap-3 p-4 mb-6 text-sm text-blue-200 border bg-blue-900/30 border-blue-700/30 rounded-2xl">
              <span className="text-2xl">💡</span>
              <div>
                <strong className="text-blue-100">Pro Tip:</strong> Use arrow keys to navigate, <kbd className="px-1 text-xs bg-blue-800 rounded">+</kbd>/<kbd className="px-1 text-xs bg-blue-800 rounded">−</kbd> to zoom, <kbd className="px-1 text-xs bg-blue-800 rounded">0</kbd> to reset.
                Scroll wheel zooms too. Click glowing <span className="text-rose-400">+</span> dots to discover points of interest!
              </div>
            </div>
          )}

          {/* ── Location cards ── */}
          <div className="grid grid-cols-2 gap-3 mb-6 sm:grid-cols-3 lg:grid-cols-5">
            {Object.keys(locationMap).map((loc) => {
              const c = LOCATION_COLORS[loc];
              const isSelected = loc === selectedLocation;
              return (
                <button
                  key={loc}
                  onClick={() => setSelectedLocation(loc)}
                  className={`relative rounded-2xl p-4 text-left transition-all border ${
                    isSelected
                      ? 'border-blue-400 shadow-lg shadow-blue-500/20 scale-105'
                      : 'border-white/5 hover:border-white/20 hover:scale-102'
                  }`}
                  style={{
                    background: isSelected
                      ? `linear-gradient(135deg, ${c.from}, ${c.to})`
                      : 'rgba(255,255,255,0.04)',
                  }}
                >
                  <div className="mb-2 text-2xl">{c.emoji}</div>
                  <div className="text-xs font-semibold leading-tight text-white">{loc}</div>
                  {isSelected && (
                    <div className="absolute w-2 h-2 bg-blue-400 rounded-full shadow-sm top-2 right-2 shadow-blue-400" />
                  )}
                </button>
              );
            })}
          </div>

          {/* ── Start button ── */}
          <div className="flex items-center gap-4 mb-6">
            <button
              onClick={handleShowPreview}
              className="flex items-center gap-2 bg-gradient-to-r from-blue-600 to-blue-500 hover:from-blue-500 hover:to-blue-400 text-white font-semibold px-8 py-3 rounded-xl shadow-lg shadow-blue-600/30 transition-all hover:shadow-blue-500/40 hover:-translate-y-0.5 active:translate-y-0"
            >
              🚀 Start Experience
            </button>
            {isPlaying && (
              <span className="flex items-center gap-2 text-sm text-green-400">
                <span className="w-2 h-2 bg-green-400 rounded-full animate-pulse" /> Now exploring: <strong>{selectedLocation}</strong>
              </span>
            )}
          </div>
        </>
      )}

      {/* ── Viewer area ── */}
      {isLoading ? (
        <div className="h-[480px] rounded-2xl overflow-hidden relative flex flex-col items-center justify-center bg-slate-800 border border-white/5">
          <div
            className="absolute inset-0 opacity-20"
            style={{
              backgroundImage: `linear-gradient(135deg, ${colors.from}, ${colors.to})`,
              animation: 'pulse 2s ease-in-out infinite',
            }}
          />
          <div className="z-10 mb-5 border-4 rounded-full w-14 h-14 border-blue-500/30 border-t-blue-500 animate-spin" />
          <p className="z-10 font-medium text-white">{selectedLocation}</p>
          <p className="z-10 mt-1 text-sm text-slate-400">Preparing immersive environment…</p>
          <p className="z-10 mt-4 text-xs text-slate-500">💡 Use fullscreen for the best experience</p>
        </div>
      ) : previewUrl ? (
        <InteractiveViewer
          selectedLocation={selectedLocation}
          locationMap={locationMap}
          isFullscreen={isFullscreen}
          setIsFullscreen={setIsFullscreen}
          zoomLevel={zoomLevel}
          handleZoomIn={handleZoomIn}
          handleZoomOut={handleZoomOut}
          resetView={resetView}
          showHotspots={showHotspots}
          setShowHotspots={setShowHotspots}
          showInfo={showInfo}
          toggleInfo={toggleInfo}
          audioEnabled={audioEnabled}
          toggleAudio={toggleAudio}
          viewMode={viewMode}
          changeViewMode={changeViewMode}
          isPlaying={isPlaying}
          chatOpen={chatOpen}
          setChatOpen={setChatOpen}
          chatMessages={chatMessages}
          chatInput={chatInput}
          setChatInput={setChatInput}
          handleChatSend={handleChatSend}
        />
      ) : (
        <div className="h-[480px] rounded-2xl border border-white/5 bg-slate-800/50 flex flex-col items-center justify-center text-center p-8 relative overflow-hidden">
          <div className="absolute inset-0 opacity-5"
            style={{ backgroundImage: 'radial-gradient(circle, #ffffff 1px, transparent 1px)', backgroundSize: '28px 28px' }} />
          <div className="z-10 mb-5 text-6xl" style={{ animation: 'float 3s ease-in-out infinite' }}>🌄</div>
          <h3 className="z-10 mb-2 text-2xl font-bold text-white">Discover Jharkhand in VR</h3>
          <p className="z-10 max-w-sm mb-6 text-sm leading-relaxed text-slate-400">
            Select a destination above and click <strong className="text-white">Start Experience</strong> to begin your virtual journey.
          </p>
          <div className="z-10 flex gap-2">
            {['🌿 Forests', '💧 Waterfalls', '🛕 Temples', '🏔️ Valleys'].map((tag) => (
              <span key={tag} className="px-3 py-1 text-xs border rounded-full bg-white/5 border-white/10 text-slate-300">{tag}</span>
            ))}
          </div>
        </div>
      )}

      {/* ── Bottom info cards ── */}
      {!isFullscreen && (
        <div className="grid grid-cols-1 gap-4 mt-8 md:grid-cols-3">
          {[
            {
              icon: '🎮', title: 'Navigation',
              items: ['↔️ Drag to look around 360°', '⬆️⬇️ Arrow keys or D-pad', '🔍 Click hotspots for info', '🖱 Scroll wheel to zoom'],
            },
            {
              icon: '📱', title: 'Device Support',
              items: ['💻 Desktop: mouse + keyboard', '📱 Mobile: touch gestures', '🥽 VR Headsets: full immersion', '🔊 Spatial audio supported'],
            },
            {
              icon: '💡', title: 'Tips',
              items: ['🎧 Headphones for spatial audio', '🚀 Strong internet recommended', '📳 Allow motion sensors on mobile', '🔲 Fullscreen for best experience'],
            },
          ].map((card) => (
            <div key={card.title} className="p-5 border bg-white/5 border-white/10 rounded-2xl backdrop-blur-sm">
              <h4 className="flex items-center gap-2 mb-3 font-bold text-white">
                <span>{card.icon}</span>{card.title}
              </h4>
              <ul className="space-y-1.5">
                {card.items.map((item) => (
                  <li key={item} className="flex items-center gap-2 text-xs text-slate-400">{item}</li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default ARVR;
